class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        count = {'N': 0, 'S': 0, 'E': 0, 'W': 0}
        ans = 0

        for i, ch in enumerate(s):
            count[ch] += 1
            steps = i + 1

            bad_counts = (
                count['S'] + count['W'],
                count['S'] + count['E'],
                count['N'] + count['W'],
                count['N'] + count['E'],
            )

            for bad in bad_counts:
                ans = max(ans, steps - 2 * max(0, bad - k))

        return ans
